fn xmlRegAtomPush(
    mut ctxt: xmlRegParserCtxtPtr,
    mut atom: xmlRegAtomPtr,
) -> c_int { unsafe {
    if atom.is_null() {
        (*ctxt).error = XML_REGEXP_COMPILE_ERROR as c_int;
        xmlRegexpErrCompile(
            ctxt,
            b"atom push: atom is NULL\0" as *const u8 as *const c_char,
        );
        return -1;
    }

    let ctxt_ref = &mut *ctxt;
    let nb_atoms = ctxt_ref.nbAtoms;

    if nb_atoms >= ctxt_ref.maxAtoms {
        let new_size = if ctxt_ref.maxAtoms != 0 {
            ctxt_ref.maxAtoms * 2
        } else {
            4
        } as size_t;

        let tmp = xmlRealloc.expect("non-null function pointer")(
            ctxt_ref.atoms as *mut c_void,
            new_size.wrapping_mul(::core::mem::size_of::<xmlRegAtomPtr>() as size_t),
        ) as *mut xmlRegAtomPtr;

        if tmp.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"allocating counter\0" as *const u8 as *const c_char,
            );
            return -1;
        }

        ctxt_ref.atoms = tmp;
        ctxt_ref.maxAtoms = new_size as c_int;
    }

    (*atom).no = nb_atoms;
    ctxt_ref.nbAtoms = nb_atoms + 1;
    // SAFETY: nb_atoms is the previous valid insertion index, and atoms points to
    // an allocation with capacity > nb_atoms after the growth check above.
    *ctxt_ref.atoms.add(nb_atoms as usize) = atom;
    0
} }

